"""Turn nominal recurrence dates into instants (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from functools import lru_cache
from math import gcd

from .errors import PlanError
from .rules import ELAPSED_UNITS

DAY_SECONDS = 86400
LAST_DAY = dt.date.max.toordinal()
EPOCH = dt.datetime(1, 1, 1, tzinfo=dt.timezone.utc)
GREGORIAN_CYCLE_MONTHS = 400 * 12


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # UTC seconds from year 1, including instants just outside datetime's range
    end: int


def instant(wall):
    """An aware wall time as UTC seconds, with its fold determining the offset."""
    return (
        (wall.toordinal() - 1) * DAY_SECONDS
        + wall.hour * 3600 + wall.minute * 60 + wall.second
        - int(wall.utcoffset().total_seconds())
    )


def local_instant(wall, zone):
    # ZoneInfo's fold=0 selects the earlier instant in a fold and the pre-gap
    # offset in a gap. The latter maps the missing time forward by the gap.
    return instant(wall.replace(tzinfo=zone, fold=0))


@lru_cache(maxsize=8192)
def _utc_datetime(seconds):
    return EPOCH + dt.timedelta(seconds=seconds)


def _wall_time(seconds, zone):
    if 0 <= seconds < LAST_DAY * DAY_SECONDS:
        return _utc_datetime(seconds).astimezone(zone)
    # A local time near year 1 or 9999 can be representable even
    # when its UTC date lies just outside datetime's calendar.
    day = 1 if seconds < 0 else LAST_DAY - 2
    reference = EPOCH + dt.timedelta(days=day)
    offset = reference.astimezone(zone).utcoffset()
    wall = EPOCH + dt.timedelta(seconds=seconds + int(offset.total_seconds()))
    return wall.replace(tzinfo=dt.timezone(offset))


@lru_cache(maxsize=8192)
def _local_day(seconds, zone):
    try:
        return _wall_time(seconds, zone).toordinal()
    except OverflowError:
        return 0 if seconds < DAY_SECONDS else LAST_DAY + 1


@lru_cache(maxsize=8192)
def _timestamp(seconds, zone):
    wall = _wall_time(seconds, zone)
    # Historical IANA offsets can have seconds. Keep them in instant arithmetic
    # while rendering offsets with the minute precision specified by the API.
    text = wall.isoformat(timespec="seconds")[:25]
    if text.endswith("-00:00"):
        return text[:-6] + "+00:00"
    return text


def timestamp(seconds, ruledef):
    try:
        return _timestamp(seconds, ruledef.tz)
    except OverflowError as exc:
        raise PlanError(f"rule {ruledef.id}: timestamp is outside the supported calendar") from exc


@lru_cache(maxsize=8192)
def _utc_key(utc_minute):
    utc = _utc_datetime(utc_minute * 60)
    return utc.replace(tzinfo=None).isoformat(timespec="minutes") + "Z"


def _window_days(first, end):
    """Bound the relevant nominal dates using the maximum possible UTC offset."""
    first = (first - DAY_SECONDS) // DAY_SECONDS + 1
    last = (end + DAY_SECONDS) // DAY_SECONDS + 1
    return max(1, first), min(LAST_DAY, last)


def _aligned(first, anchor, step):
    return first + (anchor - first) % step


def _month(day):
    return (day.year - 1) * 12 + day.month - 1


@lru_cache(maxsize=128)
def _month_pattern_has_day(phase, stride, day):
    for month_index in range(phase, GREGORIAN_CYCLE_MONTHS, stride):
        year, month = divmod(month_index, 12)
        if calendar.monthrange(year + 1, month + 1)[1] >= day:
            return True
    return False


def _candidate_days(rule, first, last):
    lo = max(first, rule.start.toordinal())
    hi = min(last, (rule.until or dt.date.max).toordinal())
    if lo > hi:
        return
    if rule.unit == "day":
        start = _aligned(lo, rule.start.toordinal(), rule.every)
        for ordinal in range(start, hi + 1, rule.every):
            yield dt.date.fromordinal(ordinal)
    elif rule.unit == "week":
        anchor = rule.start.toordinal() - rule.start.weekday()
        step = 7 * rule.every
        start = _aligned(lo - dt.date.fromordinal(lo).weekday(), anchor, step)
        for monday in range(start, hi + 1, step):
            for weekday in rule.on:
                ordinal = monday + weekday
                if lo <= ordinal <= hi:
                    yield dt.date.fromordinal(ordinal)
    else:
        first, last = dt.date.fromordinal(lo), dt.date.fromordinal(hi)
        anchor = _month(rule.start)
        if rule.on[-1] != "last" and rule.on[0] > 28:
            # Within the Gregorian cycle, active months share a residue
            # modulo the gcd of the recurrence interval and the cycle length.
            stride = gcd(rule.every, GREGORIAN_CYCLE_MONTHS)
            if not _month_pattern_has_day(anchor % stride, stride, rule.on[0]):
                return
        start = _aligned(_month(first), anchor, rule.every)
        for month_index in range(start, _month(last) + 1, rule.every):
            year, month = divmod(month_index, 12)
            year, month = year + 1, month + 1
            final_day = calendar.monthrange(year, month)[1]
            days = {final_day if day == "last" else day for day in rule.on if day == "last" or day <= final_day}
            for day in sorted(days):
                candidate = dt.date(year, month, day)
                if first <= candidate <= last:
                    yield candidate


def _candidates(ruledef, first, last):
    for day in _candidate_days(ruledef.rule, first, last):
        seen = set()
        for time in ruledef.rule.at:
            wall = dt.datetime.combine(day, time)
            start = local_instant(wall, ruledef.tz)
            if start not in seen:
                seen.add(start)
                yield wall, start


def _shift_destinations(ruledef, period):
    """Map each reached destination instant to its earliest source key."""
    if period not in ruledef.shift_cache:
        ordinal = period[1] + 1
        day = dt.date.fromordinal(min(ordinal, LAST_DAY))
        extra = (ordinal - day.toordinal()) * DAY_SECONDS
        targets = {time: local_instant(dt.datetime.combine(day, time), ruledef.tz) + extra
                   for time in ruledef.rule.at}
        target_count = len(set(targets.values()))
        shifted = {}
        for wall, _ in _candidates(ruledef, *period):
            shifted.setdefault(targets[wall.time()], wall)
            if len(shifted) == target_count:
                break
        ruledef.shift_cache[period] = shifted
    return ruledef.shift_cache[period]


def _shifted_starts(ruledef, period):
    shifted = _shift_destinations(ruledef, period)
    if not shifted:
        return
    destination = period[1] + 1
    # Local readings on nearby nominal dates can resolve to the same instant.
    # No pair more than two dates apart can share an instant.
    blocked = {start for wall, start in _candidates(ruledef, destination - 2, destination + 2)
               if ruledef.holidays.containing(wall.toordinal()) is None}
    for earlier in ruledef.holidays.between(destination - 3, destination - 1):
        if earlier[1] < period[1]:
            blocked.update(_shift_destinations(ruledef, earlier))
    for start, wall in shifted.items():
        if start not in blocked:
            yield wall, start


def _calendar_candidates(ruledef, first, last):
    rule = ruledef.rule
    first = max(first, rule.start.toordinal())
    last = min(last, (rule.until or dt.date.max).toordinal())
    if first > last:
        return
    if ruledef.holiday == "keep":
        yield from _candidates(ruledef, first, last)
        return
    cursor = first
    for period in ruledef.holidays.between(first, last):
        yield from _candidates(ruledef, cursor, period[0] - 1)
        if ruledef.holiday == "shift":
            for wall, start in _shifted_starts(ruledef, period):
                if cursor <= wall.toordinal() <= last:
                    yield wall, start
        cursor = period[1] + 1
    yield from _candidates(ruledef, cursor, last)


def _calendar_starts(ruledef, first, last, count):
    search_from = ruledef.rule.start.toordinal() if count is not None else first
    for index, (wall, start) in enumerate(_calendar_candidates(ruledef, search_from, last), 1):
        if wall.toordinal() >= first:
            yield wall, start
        if index == count:
            break


def _elapsed_starts(ruledef, first, end, count):
    rule = ruledef.rule
    anchor = ruledef.anchor
    step = rule.every * ELAPSED_UNITS[rule.unit]
    holidays = ruledef.holidays if ruledef.holiday == "skip" and ruledef.holidays.ranges else None
    if rule.until is None and holidays is None:
        if count is not None:
            end = min(end, anchor + count * step)
        yield from range(_aligned(max(first, anchor), anchor, step), end, step)
        return

    until_day = rule.until.toordinal() if rule.until else None
    if until_day is not None:
        end = min(end, (until_day + 1) * DAY_SECONDS)
    start = _aligned(anchor if count is not None else max(first, anchor), anchor, step)
    while start < end:
        if holidays is None and start < (until_day - 1) * DAY_SECONDS:
            day = until_day
        else:
            day = _local_day(start, ruledef.tz)
        period = holidays.containing(day) if holidays is not None else None
        if period is not None:
            # A local date may go backwards at a clock change. Skip only
            # instants guaranteed to be within this range for any UTC offset.
            earliest_exit = (period[1] - 1) * DAY_SECONDS
            if start >= period[0] * DAY_SECONDS and earliest_exit > start:
                start = _aligned(earliest_exit, anchor, step)
                continue
        elif until_day is None or day <= until_day:
            if start >= first:
                yield start
            if count is not None:
                count -= 1
                if count == 0:
                    break
        start += step


def has_candidate(ruledef, key, counted=False):
    count = ruledef.rule.times if counted else None
    if ruledef.anchor is not None:
        # Historically, some zone offsets included seconds. The key is the UTC
        # minute containing the start, and the interval is at least one minute.
        start = instant(key.replace(tzinfo=dt.timezone.utc)) + ruledef.anchor % 60
        return next(_elapsed_starts(ruledef, start, start + 1, count), None) is not None
    day = key.toordinal()
    return any(wall == key for wall, _ in _calendar_starts(ruledef, day, day, count))


def expand_starts(ruledef, first, end):
    """Yield keys and starts of surviving candidates in the instant window."""
    count = ruledef.rule.times
    if ruledef.anchor is not None:
        for start in _elapsed_starts(ruledef, first, end, count):
            try:
                key = _utc_key(start // 60)
            except OverflowError as exc:
                raise PlanError(f"rule {ruledef.id}: UTC key is outside the supported calendar") from exc
            yield key, start
        return

    first_day, last_day = _window_days(first, end)
    if ruledef.holiday == "shift":
        period = ruledef.holidays.containing(first_day - 1)
        if period is not None:
            first_day = period[0]
    for wall, start in _calendar_starts(ruledef, first_day, last_day, count):
        if first <= start < end:
            yield wall.isoformat(timespec="minutes"), start
"""Plan loading and override validation (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from .errors import PlanError, RuleSyntaxError
from .expand import has_candidate, local_instant
from .holidays import Holidays
from .rules import Rule, parse_date, parse_datetime, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int
    holidays: Holidays
    holiday: str
    anchor: int = None      # UTC instant for minute and hour rules
    shift_cache: dict = field(default_factory=dict)


@dataclass
class Override:
    action: str
    to: int = None
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # rule id -> key string -> Override
    min_segment: int


def _zone(name, context):
    if not isinstance(name, str):
        raise PlanError(f"{context}: timezone must be an IANA zone name")
    if name not in ("localtime", "posixrules") and not name.startswith(("posix/", "right/")):
        try:
            return ZoneInfo(name)
        except (ZoneInfoNotFoundError, ValueError, UnicodeError):
            pass
    raise PlanError(f"{context}: unknown timezone {name!r}")


def _load_rules(items, default_tz, holidays):
    rules = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index} must be an object")
        rid = item.get("id")
        if not isinstance(rid, str):
            raise PlanError(f"rule #{index}: id must be a string")
        if not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"rule #{index}: invalid id {rid!r}")
        if rid in rules:
            raise PlanError(f"rule {rid}: duplicate id")
        source = item.get("rule")
        if not isinstance(source, str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(source)
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, source) from exc
        tz = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if type(priority) is not int:
            raise PlanError(f"rule {rid}: priority must be an integer")
        holiday = item.get("holiday", "keep")
        if not isinstance(holiday, str) or holiday not in ("keep", "skip", "shift"):
            raise PlanError(f"rule {rid}: holiday must be keep, skip or shift")
        anchor = None
        if rule.anchor is not None:
            if holiday == "shift":
                raise PlanError(f"rule {rid}: holiday shift is unavailable for minute and hour rules")
            anchor = local_instant(rule.anchor, tz)
        rules[rid] = RuleDef(index, rid, rule, tz, priority, holidays, holiday, anchor)
    return rules


def _override_key(value, ruledef):
    if not isinstance(value, str):
        raise PlanError(f"rule {ruledef.id}: override key must be a string")
    try:
        if ruledef.anchor is not None:
            if not value.endswith("Z"):
                raise ValueError("expected a UTC minute key")
            return value, parse_datetime(value[:-1])
        if len(value) == 10 and len(ruledef.rule.at) == 1:
            wall = dt.datetime.combine(parse_date(value), ruledef.rule.at[0])
            return wall.isoformat(timespec="minutes"), wall
        return value, parse_datetime(value)
    except ValueError as exc:
        raise PlanError(f"rule {ruledef.id}: invalid override key {value!r}") from exc


def _load_overrides(items, rules):
    overrides = {}
    latest_counted_keys = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"override #{index} must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str):
            raise PlanError(f"override #{index}: rule id must be a string")
        if rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        ruledef = rules[rid]
        key, date_time = _override_key(item.get("key"), ruledef)
        by_key = overrides.setdefault(rid, {})
        if key in by_key:
            raise PlanError(f"rule {rid}: duplicate override for {key}")
        if not has_candidate(ruledef, date_time):
            raise PlanError(f"rule {rid}: override key {key} is not an occurrence")
        if ruledef.rule.times is not None:
            latest_counted_keys[rid] = max((key, date_time), latest_counted_keys.get(rid, (key, date_time)))
        action = item.get("action")
        if not isinstance(action, str):
            raise PlanError(f"rule {rid}: override action must be a string")
        if action not in ("cancel", "move"):
            raise PlanError(f"rule {rid}: unknown override action {action!r}")
        override = Override(action)
        if action == "move":
            try:
                wall = parse_datetime(item.get("to"))
            except ValueError as exc:
                raise PlanError(f"rule {rid}: move override needs a valid 'to'") from exc
            override.to = local_instant(wall, ruledef.tz)
            override.minutes = ruledef.rule.minutes
            if "for" in item:
                override.minutes = parse_duration(item["for"])
                if override.minutes is None:
                    raise PlanError(f"rule {rid}: invalid move duration")
        by_key[key] = override

    for rid, (key, date_time) in latest_counted_keys.items():
        # If the latest key survives the count, all earlier checked keys do too.
        if not has_candidate(rules[rid], date_time, counted=True):
            raise PlanError(f"rule {rid}: override key {key} is past the count")
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"], "plan")
    if not isinstance(raw.get("rules"), list):
        raise PlanError("plan rules must be a list")
    rules = _load_rules(raw["rules"], default_tz, Holidays(raw.get("holidays", [])))
    items = raw.get("overrides", [])
    if not isinstance(items, list):
        raise PlanError("plan overrides must be a list")
    overrides = _load_overrides(items, rules)
    min_segment = 0
    if "min_segment" in raw:
        min_segment = parse_duration(raw["min_segment"])
        if min_segment is None:
            raise PlanError("plan has an invalid min_segment duration")
    return Plan(list(rules.values()), overrides, min_segment)

"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
ELAPSED_UNITS = {"minute": 60, "hour": 3600}
UNITS = {form: unit for unit in ("day", "week", "month", *ELAPSED_UNITS) for form in (unit, unit + "s")}
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
CLOCK = r"(?:[01][0-9]|2[0-3]):[0-5][0-9]"
DATETIME = re.compile(rf"{DATE}T{CLOCK}")
POSITIVE = r"[1-9][0-9]*"
DURATION = re.compile(rf"(?:({POSITIVE})d)?(?:({POSITIVE})h)?(?:({POSITIVE})m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    anchor: dt.datetime = None   # local date-time for minute and hour rules
    until: dt.date = None
    times: int = None


def parse_duration(word):
    """'1h30m' -> 90. Returns None when the word is not a duration."""
    if not isinstance(word, str) or not word:
        return None
    match = DURATION.fullmatch(word.lower())
    if match:
        return sum(int(Decimal(part)) * scale for part, scale in zip(match.groups(), (1440, 60, 1)) if part)


def format_duration(minutes):
    days, remainder = divmod(minutes, 1440)
    hours, mins = divmod(remainder, 60)
    return "".join(f"{Decimal(value)}{unit}" for value, unit in zip((days, hours, mins), "dhm") if value)


def parse_date(word):
    if not re.fullmatch(DATE, word):
        raise ValueError("expected YYYY-MM-DD")
    return dt.date.fromisoformat(word)


def parse_datetime(word):
    if not isinstance(word, str) or not DATETIME.fullmatch(word):
        raise ValueError("expected YYYY-MM-DDTHH:MM")
    return dt.datetime.fromisoformat(word)


def _positive(word):
    if not re.fullmatch(POSITIVE, word):
        raise ValueError("expected a positive integer")
    return int(Decimal(word))


def _time(word):
    if not re.fullmatch(CLOCK, word):
        raise ValueError("expected HH:MM")
    return dt.time.fromisoformat(word)


def _month_day(word):
    if word == "last":
        return word
    if not re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        raise ValueError("expected a month day")
    return int(word)


def _items(word, parse_item):
    items = [parse_item(item) for item in word.split(",")]
    if len(items) != len(set(items)):
        raise ValueError("duplicate list item")
    return items


def _month_days(word):
    return sorted(_items(word, _month_day), key=lambda day: 32 if day == "last" else day)


class _Words:
    def __init__(self, text):
        self.text = text
        self.words = [(match.start(), match.group().lower()) for match in re.finditer(r"[^ \t]+", text)]
        self.pos = 0

    def peek(self):
        return self.words[self.pos][1] if self.pos < len(self.words) else None

    def error(self, message):
        offset = self.words[self.pos][0] if self.pos < len(self.words) else len(self.text)
        return RuleSyntaxError(message, offset, self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            raise self.error(f"expected '{keyword}'")
        self.pos += 1

    def convert(self, what, fn):
        word = self.peek()
        if word is None:
            raise self.error(f"expected {what}, found end of rule")
        try:
            value = fn(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            raise self.error(f"expected {what}, found {word!r}")
        self.pos += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() is not None and re.fullmatch(r"[0-9]+", w.peek()):
        rule.every = w.convert("a count", _positive)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    elapsed = rule.unit in ELAPSED_UNITS
    if not elapsed:
        if rule.unit in ("week", "month") and w.peek() == "on":
            w.expect("on")
            if rule.unit == "month":
                rule.on = w.convert("month days", _month_days)
            else:
                rule.on = w.convert("weekdays", lambda s: sorted(_items(s, WEEKDAYS.index)))
        w.expect("at")
        rule.at = w.convert("times", lambda s: sorted(_items(s, _time)))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    if elapsed:
        rule.anchor = w.convert("a local date-time", lambda word: parse_datetime(word.upper()))
        rule.start = rule.anchor.date()
    else:
        rule.start = w.convert("a date", parse_date)
    if w.peek() == "until":
        w.expect("until")

        def parse_until(word):
            day = parse_date(word)
            return day if day >= rule.start else None

        rule.until = w.convert("a date on or after 'from'", parse_until)
    elif w.peek() == "times":
        w.expect("times")
        rule.times = w.convert("a count", _positive)
    if w.peek() is not None:
        raise w.error(f"unexpected token {w.peek()!r}")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    out = ["every", str(Decimal(rule.every)), rule.unit if rule.every == 1 else rule.unit + "s"]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    if rule.anchor is None:
        out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    out += ["from", rule.start.isoformat() if rule.anchor is None else rule.anchor.isoformat(timespec="minutes")]
    if rule.until:
        out += ["until", rule.until.isoformat()]
    if rule.times:
        out += ["times", str(Decimal(rule.times))]
    return " ".join(out)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re
from collections import defaultdict

from .errors import PlanError
from .expand import Occurrence, expand_starts, instant, timestamp
from .plan import load_plan
from .rules import CLOCK, DATE

BOUND = re.compile(rf"{DATE}T{CLOCK}(?::[0-5][0-9])?(?:Z|[+-]{CLOCK})")


def _parse_bound(text):
    if not isinstance(text, str):
        raise PlanError("date-time bound must be a string")
    if BOUND.fullmatch(text):
        # Normalize Z for Python versions that predate support in fromisoformat.
        try:
            return instant(dt.datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {text!r}")


def _query(raw, start, end):
    plan = load_plan(raw)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if lo >= hi:
        raise PlanError("end must be after start")
    return plan, lo, hi


def _collect(plan, start, end):
    found = []
    for ruledef in plan.rules:
        overrides = plan.overrides.get(ruledef.id, {})
        length = ruledef.rule.minutes * 60
        for key, begins in expand_starts(ruledef, start - length + 1, end):
            if key not in overrides:
                found.append(Occurrence(ruledef, key, begins, begins + length))

        # A move can overlap the window from any nominal date.
        for key, override in overrides.items():
            if override.action == "move":
                begins = override.to
                finishes = begins + override.minutes * 60
                if begins < end and finishes > start:
                    found.append(Occurrence(ruledef, key, begins, finishes))
    return found


def _as_dict(occ, start, end):
    return {
        "rule": occ.rule.id,
        "key": occ.key,
        "start": timestamp(start, occ.rule),
        "end": timestamp(end, occ.rule),
    }


def occurrences(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    found = _collect(plan, lo, hi)
    found.sort(key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in found]


def _segments(found):
    ranked = sorted(found, key=lambda occ: (-occ.rule.priority, occ.start, occ.rule.index, occ.key))
    starts = defaultdict(list)
    ends = set()
    for rank, occ in enumerate(ranked):
        starts[occ.start].append(rank)
        ends.add(occ.end)
    points = sorted(starts.keys() | ends)
    active = []
    segments = []
    # Whole intervals participate in the sweep. Minimum-length filtering and
    # window clipping happen only after all winning segments have been formed.
    for start, end in zip(points, points[1:]):
        for rank in starts.get(start, ()):
            heapq.heappush(active, rank)
        while active and ranked[active[0]].end <= start:
            heapq.heappop(active)
        if active:
            winner = ranked[active[0]]
            if segments and segments[-1][0] is winner and segments[-1][2] == start:
                _, start, _ = segments.pop()
            segments.append((winner, start, end))
    return segments


def agenda(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    minimum = plan.min_segment * 60
    rows = []
    for occ, start, end in _segments(_collect(plan, lo, hi)):
        trimmed = start != occ.start or end != occ.end
        if trimmed and end - start < minimum:
            continue
        start, end = max(start, lo), min(end, hi)
        if start < end:
            rows.append(_as_dict(occ, start, end))
    return rows
import codecs
import json
import sys
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
